function isHoistable(len, firstIndex, lastIndex) {
  // every index in [firstIndex, lastIndex] must satisfy 0 <= index < len
  if (firstIndex < 0) return false;
  if (lastIndex <= len) return true;   // upper-bound proof
  return false;
}

