// fast path assumes a packed array of Smis; slow path handles everything
function sumValues(arr) {
  let fast = true;
  for (let i = 0; i <= arr.length; i++) {   // probe for the assumption
    if (!Number.isInteger(arr[i])) { fast = false; break; }
  }
  if (fast) {
    let s = 0;
    for (let i = 0; i < arr.length; i++) s += arr[i];
    return s;
  }
  // slow path
  return arr.reduce((a, b) => a + Number(b), 0);
}
